    15	import com.example.lending.domain.LoanLimitExceededException;
    16	import com.example.lending.domain.Member;
    17	import com.example.lending.domain.MemberNotFoundException;
    18	import org.springframework.stereotype.Service;
    19	import org.springframework.transaction.annotation.Transactional;
    20	
    21	import java.time.LocalDate;
    22	
    23	@Service
    24	@Transactional
    25	public class LoanBookService implements LoanBookUseCase {
    26	
    27	    private final LoadMemberPort loadMemberPort;
    28	    private final LoadLoanPort loadLoanPort;
    29	    private final LoadBookPort loadBookPort;
    30	    private final SaveBookPort saveBookPort;
    31	    private final SaveLoanPort saveLoanPort;
    32	
    33	    public LoanBookService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort,
    34	                           SaveBookPort saveBookPort, SaveLoanPort saveLoanPort) {
    35	        this.loadMemberPort = loadMemberPort;
    36	        this.loadLoanPort = loadLoanPort;
    37	        this.loadBookPort = loadBookPort;
    38	        this.saveBookPort = saveBookPort;
    39	        this.saveLoanPort = saveLoanPort;
    40	    }
    41	
    42	    @Override
    43	    public Loan loanBook(LoanBookCommand command) {
    44	        // 회원 행을 잠가 같은 회원의 대출 요청이 직렬로 처리되게 한다 (대출 수 확인과 저장 사이의 경쟁 방지)
    45	        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
    46	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
    47	        if (loadLoanPort.countLoansByMemberId(member.getId()) >= Loan.MAX_LOANS_PER_MEMBER) {
    48	            throw new LoanLimitExceededException(member.getId());
    49	        }
    50	        BookJpaEntity raw = loadBookPort.findRaw(command.bookId());
    51	        if (raw == null) {
    52	            throw new BookNotFoundException(command.bookId());
    53	        }
    54	        Book book = loadBookPort.loadBook(command.bookId())
    55	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    56	        if (book.getStatus() == BookStatus.ON_LOAN) {
    57	            throw new BookAlreadyOnLoanException(book.getId());
    58	        }
    59	        Loan loan = Loan.start(book.getId(), member.getId(), LocalDate.now());
    60	        book.setStatus(BookStatus.ON_LOAN);
    61	        saveBookPort.saveBook(book);
    62	        saveLoanPort.saveLoan(loan);
    63	        return loan;
    64	    }
    65	}
